import {GAMES,validateGame,generate,numbers,wheel,sample,choose,outcomes,distribution,portfolioStats,targetProbability,repeated,checkDraw,analyzeHistory,formatPct,odds,validateLine,key} from './engine.mjs';
import {createReport} from './pdf.mjs';
const $=id=>document.getElementById(id),money=x=>'R'+x.toLocaleString('en-ZA',{minimumFractionDigits:2,maximumFractionDigits:2});
const legacy=[{...GAMES[1],id:'oldlotto',name:'Legacy Lotto / Plus (6/58)',n:58,note:'Historical format before June 2026; not a current entry',legacy:true},{...GAMES[4],id:'oldpower',name:'Legacy PowerBall / Plus (1/20)',m:20,price:5,entry:5,note:'Historical format before June 2026; not a current entry',legacy:true},{...GAMES[0],id:'olddaily',name:'Legacy Daily Lotto Plus',price:1.5,entry:4.5,note:'Retired format; historical analysis only',legacy:true}];
let selection=null,analysis=null,worker=null,activeTab='numbers',saved=[];
const storageKey='lottolab.saved.v1';
function notice(message,error=false){$('notice').textContent=message;$('notice').className='notice'+(error?' error':'');$('notice').hidden=false;}
function guard(fn){return async (...args)=>{try{await fn(...args);}catch(e){notice(e.message||'Something went wrong. Please try again.',true);}};}
function num(id,min,max,integer=false){const raw=$(id).value;if(!raw.trim())throw Error('Complete the numeric fields.');const v=Number(raw);if(!Number.isFinite(v)||v<min||v>max||(integer&&!Number.isInteger(v)))throw Error(`${$(id).previousSibling?.textContent?.trim()||id}: enter ${integer?'a whole number':'a number'} from ${min} to ${max}.`);return v;}
function game(){const id=$('game').value;if(id!=='custom')return {...[...GAMES,...legacy].find(g=>g.id===id)};return validateGame({id:'custom',name:'Custom lottery',n:num('customN',2,100,true),k:num('customK',1,10,true),m:num('customM',0,50,true),j:num('customJ',0,5,true),bonus:$('customBonus').checked,price:num('customPrice',.01,100000),entry:num('customPrice',.01,100000),note:'User-defined game. Verify its rules before use.'});}
function cancelAnalysis(){if(worker){worker.terminate();worker=null;}$('progress').hidden=true;$('analyze').disabled=false;analysis=null;$('analysisResult').replaceChildren();const p=document.createElement('p');p.className='help';p.textContent='Run analysis to account for overlap between your current lines.';$('analysisResult').append(p);$('repeatResult').textContent='';}
function group(){if(!selection||selection.groups.length!==1)throw Error('Select one game in Number studio and generate its lines first.');return selection.groups[0];}
function getCost(){return selection.groups.reduce((sum,{g,lines})=>sum+lines.length*(selection.groups.length>1?g.price:g.entry),0);}
function ball(n,extra=false){const el=document.createElement('span');el.className='ball'+(extra?' extra':'');el.textContent=String(n).padStart(2,'0');return el;}
function render(){cancelAnalysis();const all=selection.groups.length>1,first=selection.groups[0],g=first.g,lines=first.lines;$('selectionTitle').textContent=all?'All South African games':g.name;$('lineBadge').textContent=all?`${selection.groups.length} games`:`${lines.length} unique lines`;$('selectionMeta').textContent=all?'Linked add-ons share base-game numbers · '+selection.strategy:`${g.k} from ${g.n}${g.m?' + '+g.j+' from '+g.m:''} · ${selection.strategy}${g.legacy?' · Historical only':''}`;const boards=$('boards');boards.replaceChildren();selection.groups.forEach(({g,lines})=>{if(all){const h=document.createElement('h3');h.className='group-title';h.textContent=g.name;boards.append(h);}lines.forEach((l,i)=>{const row=document.createElement('div');row.className='board';const idx=document.createElement('span');idx.className='board-number';idx.textContent=String(i+1).padStart(2,'0');const balls=document.createElement('div');balls.className='balls';l.main.forEach(n=>balls.append(ball(n)));if(l.extra.length){const plus=document.createElement('span');plus.className='ball-plus';plus.textContent='+';balls.append(plus);l.extra.forEach(n=>balls.append(ball(n,true)));}row.append(idx,balls);boards.append(row);});});const cost=getCost();$('cost').textContent=money(cost);$('costLabel').textContent=all?'All-game ticket cost':'Required ticket cost';$('costHelp').textContent=all?'All linked entries included':g.entry>g.price?'Includes required base entries':'Excludes retailer fees';$('costHelp').className='';const budget=Number($('budget').value);if(Number.isFinite(budget)&&cost>budget){$('costHelp').textContent='Over your '+money(budget)+' budget';$('costHelp').className='budget-warning';}if(all){$('jackpotOdds').textContent='Per game';$('jackpotPercent').textContent='Exact odds included in PDF';$('coverage').textContent=selection.groups.reduce((s,x)=>s+x.lines.length,0)+' entries';$('coverageHelp').textContent='Across 6 separate draws';}else{const stats=portfolioStats(g,lines);$('jackpotOdds').textContent=odds(stats.jackpot);$('jackpotPercent').textContent=formatPct(stats.jackpot)+' · selected draw';$('coverage').textContent=stats.coverage+' / '+g.n;$('coverageHelp').textContent='Distinct main numbers';}renderOdds();}
function generateCurrent(){const g=game(),strategy=$('strategy').value;let lines;if(strategy==='wheel'){const pool=numbers($('wheelPool').value,g.n),extra=sample(Array.from({length:g.m},(_,i)=>i+1),g.j);lines=wheel(g,pool,extra);}else{lines=generate(g,num('lineCount',1,200,true),{locked:numbers($('locked').value,g.n),excluded:numbers($('excluded').value,g.n),strategy});}selection={created:new Date().toISOString(),strategy:{random:'Uniform random',spread:'Spread across lines',wheel:'Full combination wheel'}[strategy],groups:[{g,lines}]};render();}
function gameChange(){const g=game();$('customFields').hidden=$('game').value!=='custom';$('gameDescription').textContent=g.note+` · ${money(g.entry)} per required ticket line`;$('locked').value='';$('excluded').value='';$('wheelPool').value='';$('strategy').value='random';styleChange();$('drawMain').value='';$('drawExtra').value='';$('drawBonus').value='';$('checkResult').replaceChildren();$('historyResult').replaceChildren();generateCurrent();}
function styleChange(){const s=$('strategy').value;$('wheelFields').hidden=s!=='wheel';$('preferences').hidden=s==='wheel';$('strategyHelp').textContent=s==='random'?'Every valid combination has the same chance.':s==='spread'?'Reduces repeated main numbers between lines. A coverage heuristic, not a prediction.':'Covers every combination within your chosen pool. Costs increase with the number of combinations.';}
function renderOdds(){const all=selection.groups.length>1;$('analyze').disabled=all;$('oddsRows').replaceChildren();$('payoutInputs').replaceChildren();$('heatmap').replaceChildren();$('evResult').textContent='';if(all){$('oddsRows').innerHTML='<tr><td colspan="3">Select a single game to explore its odds.</td></tr>';$('target').replaceChildren();$('overlap').textContent='';return;}const {g,lines}=group(),rows=distribution(g);for(const row of rows){const tr=document.createElement('tr');for(const val of [row.label,formatPct(row.p),odds(row.p)]){const td=document.createElement('td');td.textContent=val;tr.append(td);}$('oddsRows').append(tr);const label=document.createElement('label');label.textContent=row.label+' (R)';const input=document.createElement('input');input.type='number';input.min='0';input.max='100000000000';input.step='.01';input.placeholder='0';input.dataset.probability=row.p;input.addEventListener('input',guard(updateEV));label.append(input);$('payoutInputs').append(label);}$('target').replaceChildren();for(let r=1;r<=g.k;r++){const o=document.createElement('option');o.value=r;o.textContent=r+' main matches';o.selected=r===Math.min(4,g.k);$('target').append(o);}$('requireExtra').disabled=!g.m;$('requireExtra').checked=false;const stats=portfolioStats(g,lines);stats.frequency.forEach((f,i)=>{const cell=document.createElement('span');cell.className='heat-cell'+(f?' used':'');cell.textContent=i+1;cell.title=`${f} appearances`;$('heatmap').append(cell);});$('overlap').textContent=`${stats.coverage} of ${g.n} main numbers covered. Average pair overlap: ${stats.overlap.toFixed(2)} main numbers. Coverage is not a win guarantee.`;updateEV();}
function updateEV(){const {g}=group();let gross=0;for(const input of $('payoutInputs').querySelectorAll('input')){const v=input.value===''?0:Number(input.value);if(!Number.isFinite(v)||v<0||v>1e11)throw Error('Payouts must be between R0 and R100 billion.');gross+=v*Number(input.dataset.probability);}$('evResult').textContent=`Expected gross ${money(gross)} − ticket ${money(g.entry)} = ${money(gross-g.entry)} net per line, under your payout assumptions.`;}
function repeatResult(){if(!analysis)return;const d=num('draws',1,100000,true);$('repeatResult').textContent=`Over ${d.toLocaleString()} independent draws: ${formatPct(repeated(analysis.p,d))}${analysis.exact?'':' estimated'} chance of reaching the target at least once. Total ticket cost: ${money(getCost()*d)}.`;if(!analysis.exact)$('repeatResult').textContent+=` Simulation interval propagated: ${formatPct(repeated(analysis.low,d))}–${formatPct(repeated(analysis.high,d))}.`;}
function startAnalysis(){const {g,lines}=group();cancelAnalysis();const r=Number($('target').value),extra=$('requireExtra').checked&&!!g.m;worker=new Worker(new URL('./worker.mjs',import.meta.url),{type:'module'});$('analyze').disabled=true;$('progress').hidden=false;$('progress').value=0;$('analysisResult').textContent='Calculating coverage…';worker.onerror=()=>{cancelAnalysis();notice('Analysis worker could not run in this browser. Exact single-line odds are still available.',true);};worker.onmessage=({data:a})=>{if(a.error){cancelAnalysis();notice(a.error,true);return;}if(!a.done){$('progress').value=a.progress;return;}analysis={...a,r,extra};worker.terminate();worker=null;$('analyze').disabled=false;$('progress').hidden=true;const result=$('analysisResult');result.replaceChildren();const h=document.createElement('strong');h.textContent=formatPct(a.p);const p=document.createElement('p');p.textContent=a.exact?`Exact chance of at least ${r} main matches${extra?' and all extra balls':''} on one or more of your lines.`:`Simulation estimate from ${a.n.toLocaleString()} independent trials. 95% interval: ${formatPct(a.low)}–${formatPct(a.high)}. ${a.hits===0?'No hits were observed; this does not mean the event is impossible.':''}`;result.append(h,p);guard(repeatResult)();};worker.postMessage({g,lines,r,extra,trials:60000});}
function exportPDF(){if(!selection)return;const report={...selection,analysis};const bytes=createReport(report),blob=new Blob([bytes],{type:'application/pdf'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='LottoLab-'+(selection.groups.length>1?'all-games':selection.groups[0].g.id)+'-'+new Date().toISOString().slice(0,10)+'.pdf';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);notice('PDF created. Check your browser downloads.');}
function validateSelection(s){if(!s||!Array.isArray(s.groups)||s.groups.length<1||s.groups.length>6||typeof s.created!=='string'||!Number.isFinite(Date.parse(s.created))||typeof s.strategy!=='string')throw Error('Invalid saved selection.');for(const {g,lines} of s.groups){validateGame(g);if(typeof g.name!=='string'||g.name.length>100||!Number.isFinite(g.price)||g.price<0||!Number.isFinite(g.entry)||g.entry<0||!Array.isArray(lines)||lines.length<1||lines.length>200)throw Error('Invalid saved game.');lines.forEach(l=>validateLine(g,l));if(new Set(lines.map(key)).size!==lines.length)throw Error('Duplicate saved lines.');}return s;}
function renderSaved(){$('savedCount').textContent=saved.length;const host=$('savedList');host.replaceChildren();if(!saved.length){host.innerHTML='<div class="empty">No selections saved yet.<br>Generate your numbers, then tap Save selection.</div>';return;}saved.forEach((s,i)=>{const div=document.createElement('div');div.className='panel saved-card';const body=document.createElement('div'),h=document.createElement('h2'),p=document.createElement('p');h.textContent=s.groups.length>1?'All South African games':s.groups[0].g.name;p.textContent=`${s.groups.reduce((a,g)=>a+g.lines.length,0)} entries · ${new Date(s.created).toLocaleString('en-ZA')} · ${s.strategy}`;body.append(h,p);const actions=document.createElement('div');actions.className='actions';const load=document.createElement('button');load.className='button secondary';load.textContent='Open selection';load.onclick=guard(()=>{selection=structuredClone(validateSelection(s));if(s.groups.length===1){const g=s.groups[0].g;$('game').value=g.id;if(g.id==='custom'){for(const [id,val] of [['customN',g.n],['customK',g.k],['customM',g.m],['customJ',g.j],['customPrice',g.entry]])$(id).value=val;$('customBonus').checked=g.bonus;}$('customFields').hidden=g.id!=='custom';$('gameDescription').textContent=g.note||'Saved game';$('lineCount').value=s.groups[0].lines.length;}render();switchTab('numbers');notice('Saved selection restored.');});const del=document.createElement('button');del.className='button ghost';del.textContent='Delete';del.onclick=guard(()=>{const next=saved.filter((_,idx)=>idx!==i);localStorage.setItem(storageKey,JSON.stringify(next));saved=next;renderSaved();});actions.append(load,del);div.append(body,actions);host.append(div);});}
function switchTab(id){if(!['numbers','odds','tools','saved'].includes(id))id='numbers';activeTab=id;document.querySelectorAll('.tab-panel').forEach(p=>p.hidden=p.id!==id);document.querySelectorAll('.nav').forEach(b=>{b.classList.toggle('active',b.dataset.tab===id);b.setAttribute('aria-current',b.dataset.tab===id?'page':'false');});$('pageLabel').textContent={numbers:'Number studio',odds:'Odds & coverage',tools:'Draw tools',saved:'Saved selections'}[id];window.scrollTo({top:0,behavior:'instant'});}
for(const g of GAMES){const o=document.createElement('option');o.value=g.id;o.textContent=g.name;$('game').append(o);}const og=document.createElement('optgroup');og.label='Historical analysis only';for(const g of legacy){const o=document.createElement('option');o.value=g.id;o.textContent=g.name;og.append(o);}$('game').append(og);const custom=document.createElement('option');custom.value='custom';custom.textContent='Custom / international format';$('game').append(custom);
$('game').onchange=guard(()=>{if($('game').value==='custom')$('customFields').hidden=false;gameChange();});$('strategy').onchange=styleChange;$('generate').onclick=guard(generateCurrent);$('fitBudget').onclick=guard(()=>{const g=game(),count=Math.min(200,Math.floor(num('budget',0,100000)/g.entry));if(!count)throw Error('Budget is below the price of one required ticket line.');$('lineCount').value=count;notice(`${count} lines fit your budget, before retailer fees. Tap Generate numbers to apply.`);});$('budget').onchange=guard(()=>{num('budget',0,100000);render();});$('generateAll').onclick=guard(()=>{const count=num('lineCount',1,200,true),daily=generate(GAMES[0],count),lotto=generate(GAMES[1],count),power=generate(GAMES[4],count);selection={created:new Date().toISOString(),strategy:'Uniform random',groups:GAMES.map(g=>({g:{...g},lines:structuredClone(g.id==='daily'?daily:g.m?power:lotto)}))};render();notice('Generated all six games. Linked Lotto and PowerBall add-ons share their base-game numbers.');});
for(const id of ['export','exportTop'])$(id).onclick=guard(exportPDF);$('copy').onclick=guard(async()=>{const text=selection.groups.map(({g,lines})=>g.name+'\n'+lines.map((l,i)=>(i+1)+'. '+l.main.join(', ')+(l.extra.length?' + '+l.extra.join(', '):'')).join('\n')).join('\n\n');if(!navigator.clipboard)throw Error('Clipboard is unavailable in this browser. Use PDF export.');await navigator.clipboard.writeText(text);notice('Numbers copied.');});$('save').onclick=guard(()=>{const next=[structuredClone(selection),...saved].slice(0,50);localStorage.setItem(storageKey,JSON.stringify(next));saved=next;renderSaved();notice('Selection saved on this device. Up to 50 recent selections are kept.');});$('analyze').onclick=guard(startAnalysis);$('target').onchange=cancelAnalysis;$('requireExtra').onchange=cancelAnalysis;$('draws').onchange=guard(repeatResult);
$('check').onclick=guard(()=>{const {g,lines}=group(),main=numbers($('drawMain').value,g.n),extra=numbers($('drawExtra').value,g.m),bonus=$('drawBonus').value===''?null:Number($('drawBonus').value);const result=checkDraw(g,lines,main,extra,bonus);$('checkResult').replaceChildren();result.forEach((m,i)=>{const row=document.createElement('div');row.className='check-row';row.textContent=`Line ${i+1}: ${m.main} main${g.m?' + '+m.extra+' extra':''}${m.bonus?' + bonus':''}`;$('checkResult').append(row);});});$('historyAnalyze').onclick=guard(()=>{const {g}=group(),data=analyzeHistory(g,$('history').value),host=$('historyResult');host.replaceChildren();const p=document.createElement('p');p.className='help';p.textContent=`${data.draws} draws · expected appearances per number: ${data.mean.toFixed(2)}. Showing all numbers by frequency; this is descriptive only.`;host.append(p);const max=data.values[0].count||1;data.values.forEach(v=>{const row=document.createElement('div');row.className='history-bar';const n=document.createElement('span');n.textContent=String(v.n).padStart(2,'0');const b=document.createElement('b');b.style.width=(v.count/max*100)+'%';const c=document.createElement('span');c.textContent=v.count+' times';row.append(n,b,c);host.append(row);});});document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));
try{const raw=localStorage.getItem(storageKey);if(raw){const parsed=JSON.parse(raw);if(!Array.isArray(parsed)||parsed.length>50)throw Error('Invalid saved collection.');saved=parsed.map(validateSelection);}}catch{notice('Saved selections could not be loaded. You can still generate numbers and export PDFs.',true);}renderSaved();guard(gameChange)();
